parts.openscad_module:
$fn = 128;

pipe_od        = 25;
clamp_width    = 30;
wall_thickness = 5;
bolt_span      = 40;
flange_height  = 12;

module pipe_saddle_clamp() {
  difference() {
    union() {
      intersection() {
        cylinder(h = clamp_width, d = pipe_od + 2*wall_thickness, center = true);
        translate([0, (pipe_od/2 + wall_thickness)/2, 0])
          cube([pipe_od + 2*wall_thickness, pipe_od + 2*wall_thickness, clamp_width + 2], center = true);
      }
      for (s = [-1, 1])
        translate([s * bolt_span/2, -(pipe_od/2 + wall_thickness/2), 0])
          cube([10, flange_height, clamp_width], center = true);
    }
    cylinder(h = clamp_width + 2, d = pipe_od + 0.6, center = true);
    for (s = [-1, 1])
      translate([s * bolt_span/2, -(pipe_od/2), 0])
        cylinder(h = clamp_width + 2, d = 5.5, center = true, $fn = 32);
  }
}

pipe_saddle_clamp();
